//go:build darwin

// sc_app.m is the Cocoa + MetalKit host. It is compiled by cgo as Objective-C
// (its extension picks the language) and is the only Objective-C in the tree.
// Memory management is manual (no ARC): every object it makes is stored in a
// static global and lives for the whole run, which is what a single-window
// app wants anyway.

#import "sc_app.h"
#include "_cgo_export.h" // goDraw / goResize, generated by cgo

#import <Cocoa/Cocoa.h>
#import <Metal/Metal.h>
#import <MetalKit/MetalKit.h>
#import <stdio.h>
#import <stdlib.h>
#import <string.h>

static NSString *gTitle = @"ScottiCAD";
static int gW = 1280;
static int gH = 800;
static int gVisible = 1;
static double gClear[4] = {0.12, 0.13, 0.15, 1.0};

static id<MTLDevice> gDevice = nil;
static id<MTLCommandQueue> gQueue = nil;
static NSWindow *gWindow = nil;
static MTKView *gView = nil;

@interface SCAppDelegate : NSObject <NSApplicationDelegate, NSWindowDelegate, MTKViewDelegate>
@end

@implementation SCAppDelegate

- (void)applicationDidFinishLaunching:(NSNotification *)note {
	gDevice = MTLCreateSystemDefaultDevice();
	if (gDevice == nil) {
		fprintf(stderr, "scotticad: no Metal device available\n");
		[NSApp terminate:nil];
		return;
	}
	gQueue = [gDevice newCommandQueue];

	NSRect frame = NSMakeRect(0, 0, (CGFloat)gW, (CGFloat)gH);
	NSWindowStyleMask style = NSWindowStyleMaskTitled |
	                          NSWindowStyleMaskClosable |
	                          NSWindowStyleMaskMiniaturizable |
	                          NSWindowStyleMaskResizable;
	gWindow = [[NSWindow alloc] initWithContentRect:frame
	                                      styleMask:style
	                                        backing:NSBackingStoreBuffered
	                                          defer:NO];
	gWindow.title = gTitle;
	gWindow.delegate = self;
	[gWindow center];

	// MTKView owns a CAMetalLayer and drives frames itself (paused=NO): it
	// calls drawInMTKView: on the main thread, which is where we call goDraw.
	gView = [[MTKView alloc] initWithFrame:frame device:gDevice];
	gView.colorPixelFormat = MTLPixelFormatBGRA8Unorm;
	gView.depthStencilPixelFormat = MTLPixelFormatInvalid;
	gView.preferredFramesPerSecond = 60;
	gView.paused = NO;
	gView.enableSetNeedsDisplay = NO;
	gView.autoResizeDrawable = YES; // the drawable follows the Retina scale
	gView.clearColor = MTLClearColorMake(gClear[0], gClear[1], gClear[2], gClear[3]);
	gView.delegate = self;
	gWindow.contentView = gView;

	[self installMenu];

	if (gVisible) {
		[gWindow makeKeyAndOrderFront:nil];
		[NSApp activateIgnoringOtherApps:YES];
	}
}

// installMenu gives the app a menu bar with the standard app menu, so that
// Cmd+Q and Cmd+H work even though the UI is otherwise self-drawn.
- (void)installMenu {
	NSMenu *menubar = [[NSMenu alloc] init];
	NSMenuItem *appItem = [[NSMenuItem alloc] init];
	[menubar addItem:appItem];
	[NSApp setMainMenu:menubar];

	NSString *name = [[NSProcessInfo processInfo] processName];
	NSMenu *appMenu = [[NSMenu alloc] init];
	[appMenu addItemWithTitle:[@"About " stringByAppendingString:name]
	                   action:@selector(orderFrontStandardAboutPanel:)
	            keyEquivalent:@""];
	[appMenu addItem:[NSMenuItem separatorItem]];
	[appMenu addItemWithTitle:[@"Hide " stringByAppendingString:name]
	                   action:@selector(hide:)
	            keyEquivalent:@"h"];
	[appMenu addItem:[NSMenuItem separatorItem]];
	[appMenu addItemWithTitle:[@"Quit " stringByAppendingString:name]
	                   action:@selector(terminate:)
	            keyEquivalent:@"q"];
	appItem.submenu = appMenu;
}

- (BOOL)applicationShouldTerminateAfterLastWindowClosed:(NSApplication *)app {
	return YES;
}

- (void)windowWillClose:(NSNotification *)note {
	[NSApp terminate:nil];
}

- (void)mtkView:(MTKView *)view drawableSizeWillChange:(CGSize)size {
	goResize((int)size.width, (int)size.height);
}

- (void)drawInMTKView:(MTKView *)view {
	goDraw(); // may set this frame's clear colour through sc_clear

	id<CAMetalDrawable> drawable = view.currentDrawable;
	if (drawable == nil) {
		return;
	}
	MTLRenderPassDescriptor *rp = view.currentRenderPassDescriptor;
	if (rp == nil) {
		return;
	}
	rp.colorAttachments[0].clearColor = MTLClearColorMake(gClear[0], gClear[1], gClear[2], gClear[3]);
	rp.colorAttachments[0].loadAction = MTLLoadActionClear;
	rp.colorAttachments[0].storeAction = MTLStoreActionStore;

	id<MTLCommandBuffer> cb = [gQueue commandBuffer];
	id<MTLRenderCommandEncoder> enc = [cb renderCommandEncoderWithDescriptor:rp];
	[enc endEncoding];
	[cb presentDrawable:drawable];
	[cb commit];
}

@end

static SCAppDelegate *gDelegate = nil;

void sc_run(const char *title, int w, int h, int visible) {
	@autoreleasepool {
		if (title != NULL) {
			gTitle = [NSString stringWithUTF8String:title];
		}
		gW = w;
		gH = h;
		gVisible = visible;

		[NSApplication sharedApplication];
		[NSApp setActivationPolicy:NSApplicationActivationPolicyRegular];

		gDelegate = [[SCAppDelegate alloc] init];
		NSApp.delegate = gDelegate;

		[NSApp run];
	}
}

void sc_end(void) {
	dispatch_async(dispatch_get_main_queue(), ^{
		[NSApp terminate:nil];
	});
}

void sc_set_title(const char *title) {
	if (title == NULL) {
		return;
	}
	// Copy the C string into the block: the caller's buffer may be gone by
	// the time the main queue runs the block.
	char *copy = strdup(title);
	dispatch_async(dispatch_get_main_queue(), ^{
		if (gWindow != nil) {
			gWindow.title = [NSString stringWithUTF8String:copy];
		}
		free(copy);
	});
}

void sc_clear(double r, double g, double b, double a) {
	gClear[0] = r;
	gClear[1] = g;
	gClear[2] = b;
	gClear[3] = a;
}
